import{_ as t,o,c as a,ag as d}from"./chunks/framework.8tqBsFWt.js";const g=JSON.parse('{"title":"Postgres migration — Phase 0 decision memo","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/postgres-migration.md","filePath":"decisions/postgres-migration.md"}'),s={name:"decisions/postgres-migration.md"};function r(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="postgres-migration-—-phase-0-decision-memo" tabindex="-1">Postgres migration — Phase 0 decision memo <a class="header-anchor" href="#postgres-migration-—-phase-0-decision-memo" aria-label="Permalink to &quot;Postgres migration — Phase 0 decision memo&quot;">​</a></h1><p><strong>Status: complete (2026-05-14).</strong> Sheets decommissioned in <a href="https://github.com/talktalkmake/VERA/issues/640" target="_blank" rel="noreferrer">#640</a>; the codebase is now Postgres-only and the dispatcher/dual-write machinery described below has been removed. The historical record stays in place because it shaped every design choice that survives.</p><p><strong>Issue:</strong> <a href="https://github.com/talktalkmake/VERA/issues/438" target="_blank" rel="noreferrer">#438</a> · <strong>Branch:</strong> merged to <code>main</code> · <strong>Date:</strong> 2026-04-21 · <strong>Phase:</strong> 0 (scoping)</p><p>This memo records the three Phase 0 decisions called for in <a href="https://github.com/talktalkmake/VERA/issues/438" target="_blank" rel="noreferrer">#438</a> (host, migration tool, confidence window) and summarises the contract that Phase 1 must preserve when it rewrites the DAL. It supersedes the pre-trigger plan at <a href="https://github.com/talktalkmake/VERA/blob/main/migration-plan.md" target="_blank" rel="noreferrer">migration-plan.md</a> (2026-03-23) — that file remains for historical reference but the dispatcher + dual-write architecture in <a href="https://github.com/talktalkmake/VERA/issues/438" target="_blank" rel="noreferrer">#438</a> is now canonical.</p><hr><h2 id="status-as-of-2026-04-24-—-phase-2-5-complete-phase-3-ready" tabindex="-1">Status as of 2026-04-24 — Phase 2.5 complete, Phase 3 ready <a class="header-anchor" href="#status-as-of-2026-04-24-—-phase-2-5-complete-phase-3-ready" aria-label="Permalink to &quot;Status as of 2026-04-24 — Phase 2.5 complete, Phase 3 ready&quot;">​</a></h2><p>Phases 0 through 2.5 have landed on <code>main</code>. The data access layer is now a dispatcher (<code>lib/dal.js</code>) with two backends (<code>lib/dal.sheets.js</code>, <code>lib/dal.postgres.js</code>) and a per-table <code>BACKEND</code> map routing to <code>sheets</code> / <code>postgres</code> / <code>both</code>.</p><p><strong>What&#39;s live:</strong></p><ul><li><strong>All 14 tables are on <code>&#39;both&#39;</code> mode.</strong> Sheets is the primary write path; Postgres receives a best-effort shadow-write on the same transaction, gated by the <code>PG_SHADOW_WRITE_TENANTS</code> env allowlist (fail-closed: unset = no pg writes anywhere). Reads still come from Sheets exclusively.</li><li><strong>Legacy value coercion on the pg path.</strong> <code>toEmploymentType</code> (#478) and <code>toProjectType</code> (#480) normalize casing so old rows like <code>&quot;FTE&quot;</code> or <code>&quot;RETAINER&quot;</code> satisfy the Postgres enum constraints on the shadow-write path without touching the canonical Sheets value.</li><li><strong>No raw Sheets writers remain in callers.</strong> Issue <a href="https://github.com/talktalkmake/VERA/issues/482" target="_blank" rel="noreferrer">#482</a> (Clusters A–E, PRs #483–#487, merged 2026-04-23/24) closed 12 bypass sites across <code>mcp-server.js</code> where <code>spreadsheets.values.append/update</code> or <code>appendRowsToSheet</code> were called directly. Every write now dispatches through <code>lib/dal.js</code> so pg shadow-writes fire on every code path. This is an invariant going forward; CLAUDE.md&#39;s DAL section documents the enforcement rule.</li><li><strong>New typed updaters on both backends (Clusters A–E):</strong> <code>updateClientName</code>, <code>updateProjectStatus</code>, <code>updateProjectType</code>, <code>updateProjectIsBillable</code>, <code>updateProjectContractValue</code>, <code>updateProjectBillingRate</code>, <code>updateProjectAlertThreshold</code>, <code>updateProjectNotes</code>, <code>updateUserSlackId</code>, <code>updateUserEmploymentType</code>, <code>updateProjectPeriodStatus</code>, <code>updateUnresolvedItemStatus</code>. <code>update_project</code> was refactored from a full-row rewrite into per-field DAL calls; <code>updateProjectBudget</code>/<code>updateProjectDeadline</code> were hardened to accept <code>&#39;&#39;</code>/<code>null</code> as the clear signal.</li><li><strong><code>rename_client</code> tool shipped</strong> (#481, PR #483) — owner-only, Internal-protected, collision-checked.</li><li><strong>Test suite: 455/455</strong> on <code>main</code>.</li></ul><p><strong>What&#39;s next — Phase 3 (read migration):</strong></p><p>Flipping one table at a time by changing <code>BACKEND[table]</code> from <code>&#39;both&#39;</code> to <code>&#39;postgres&#39;</code> switches reads (and writes) for that table to pg. Pre-flip checklist per table:</p><ol><li>Run the diff-store reconciliation job on T0ADQ6UAVKR across a representative time window; confirm zero mismatches.</li><li>Confirm every FK parent is already on <code>&#39;postgres&#39;</code> (or still on <code>&#39;both&#39;</code> with reconciled rows — a <code>&#39;postgres&#39;</code> child cannot FK to a Sheets-only parent).</li><li>Flip, deploy, watch for 24–48h, then either promote to the next table or roll back by flipping back to <code>&#39;both&#39;</code>.</li></ol><p>Tables should flip in dependency order: <code>tenants</code> (not in the dispatcher; already the fixed reference) → <code>clients</code>, <code>users</code>, <code>disciplines</code>, <code>tasks</code>, <code>company_calendar</code> (no FK parents) → <code>projects</code> (FK → clients, users) → everything else (FK → projects + users).</p><p>The 8-week confidence window (§0.4 below) starts when the first table flips to <code>&#39;postgres&#39;</code>. Phase 4 deletes the Sheets path only after zero mismatches and zero flag flips across the window.</p><h2 id="_0-1-—-the-contract-lib-dal-js" tabindex="-1">0.1 — The contract: <code>lib/dal.js</code> <a class="header-anchor" href="#_0-1-—-the-contract-lib-dal-js" aria-label="Permalink to &quot;0.1 — The contract: `lib/dal.js`&quot;">​</a></h2><p><code>lib/dal.js</code> (757 lines) is the only module that touches Google Sheets by column index. Phase 1&#39;s <code>dal.postgres.js</code> must expose the same public API so callers do not change. Consumers are eight files; the DAL is imported 392 times across the repo.</p><table tabindex="0"><thead><tr><th>File</th><th>Import count</th></tr></thead><tbody><tr><td><code>mcp-server.js</code></td><td>207</td></tr><tr><td><code>envelopes.js</code></td><td>51</td></tr><tr><td><code>budgets.js</code></td><td>37</td></tr><tr><td><code>tests/mcp-routes.test.js</code></td><td>17</td></tr><tr><td><code>rates.js</code></td><td>10</td></tr><tr><td><code>liabilities.js</code></td><td>9</td></tr><tr><td><code>lib/availability.js</code></td><td>3</td></tr><tr><td><code>lib/unresolved.js</code></td><td>3</td></tr><tr><td><code>demo-seed.js</code></td><td>2</td></tr></tbody></table><p><strong>Exported surface (56 symbols):</strong></p><ul><li><strong>Cache</strong> — <code>cachedSheetGet</code>, <code>setCacheEntry</code>, <code>bustCache</code></li><li><strong>WAL</strong> — <code>addTimeEntryWALEntry</code>, <code>getTimeEntryWALEntries</code>, <code>addBudgetWALEntry</code>, <code>addConversationWALEntry</code>, <code>getConversationWALEntries</code></li><li><strong>Helpers</strong> — <code>sanitizeSlackId</code>, <code>findUserByName</code>, <code>findProjectByName</code>, <code>buildIndex</code></li><li><strong>Readers (12)</strong> — <code>readUsers</code>, <code>readProjects</code>, <code>readTimeEntries</code>, <code>readTasks</code>, <code>readProjectTasks</code>, <code>readClients</code>, <code>readBudgets</code>, <code>readDisciplines</code>, <code>readCompanyCalendar</code>, <code>readPendingPTO</code>, <code>readRateHistory</code>, <code>readLiabilities</code></li><li><strong>Generic writers</strong> — <code>appendToSheet</code>, <code>appendRowsToSheet</code>, <code>updateCell</code>, <code>updateRange</code></li><li><strong>Typed appends (14)</strong> — <code>appendTimeEntry</code>, <code>appendProject</code>, <code>appendUser</code>, <code>appendClient</code>, <code>appendTask</code>, <code>appendProjectTask</code>, <code>appendBudget</code>, <code>appendDiscipline</code>, <code>appendConversation</code>, <code>appendPendingPTO</code>, <code>appendCalendarEvent</code>, <code>appendRateHistory</code>, <code>appendLiability</code>, <code>appendUnresolvedItem</code></li><li><strong>Typed updates (~20)</strong> — users (role/name/status), projects (PM/budget/deadline/name/period_status/period_start/period_end), time entries (row/user/project/task), budgets (hours/status/task), tasks (name), PTO (approval/rejection), unresolved items (status)</li></ul><p><strong>Contract-preserving notes for Phase 1:</strong></p><ul><li><code>cachedSheetGet(range)</code> and <code>setCacheEntry</code> survive the cutover window — they stay in the dispatcher layer so the Sheets path continues to work during dual-write. Deleted in Phase 4.</li><li>WAL exports (<code>add*WALEntry</code>, <code>get*WALEntries</code>) stay in the dispatcher and continue to back the Sheets path during dual-write. Once Postgres is the source of truth the WAL is obsolete and removed in Phase 4; Postgres itself has read-after-write consistency so no equivalent is needed.</li><li><code>bustCache(tabName)</code> becomes a no-op on the Postgres path; the Sheets path still calls it, so the dispatcher keeps the export.</li><li><code>sanitizeSlackId</code>, <code>findUserByName</code>, <code>findProjectByName</code>, <code>buildIndex</code> are pure helpers — no backend involvement. They live in a shared <code>lib/dal-helpers.js</code> and are re-exported by both backends.</li><li><code>mcp-server.js</code> has <strong>two</strong> <code>require(&#39;./lib/dal&#39;)</code> blocks (line 12 and line 1409). Consolidate into one in Phase 1.5 when the dispatcher lands.</li></ul><h2 id="_0-2-—-host-supabase" tabindex="-1">0.2 — Host: Supabase <a class="header-anchor" href="#_0-2-—-host-supabase" aria-label="Permalink to &quot;0.2 — Host: Supabase&quot;">​</a></h2><p><strong>Decision: Supabase (two projects: <code>vera-staging</code>, <code>vera-prod</code>). Connect via raw <code>pg</code> driver. Do not adopt <code>supabase-js</code>.</strong></p><table tabindex="0"><thead><tr><th>Criterion</th><th>Railway PG</th><th>Neon</th><th><strong>Supabase</strong></th></tr></thead><tbody><tr><td>Co-located with app (Railway)</td><td>✅</td><td>➖ network hop</td><td>➖ network hop</td></tr><tr><td>Staging/prod split on free tier</td><td>➖ paid</td><td>✅ branches</td><td>✅ two projects</td></tr><tr><td>Row-level security first-class</td><td>➖ plain PG</td><td>➖ plain PG</td><td>✅</td></tr><tr><td>Data-inspection UI (replaces Sheets&#39; visual feel for the owner)</td><td>❌</td><td>➖ limited</td><td>✅ Table editor</td></tr><tr><td>Point-in-time recovery on free/low tier</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>Works with raw <code>pg</code> driver (no SDK lock-in)</td><td>✅</td><td>✅</td><td>✅</td></tr></tbody></table><p><strong>Why Supabase wins:</strong></p><ul><li>The Sheets-to-Postgres migration threatens one genuine Sheets benefit: Tom can <em>see the data</em> without writing SQL. Supabase&#39;s Table editor preserves that affordance at zero extra cost.</li><li><a href="https://github.com/talktalkmake/VERA/issues/438" target="_blank" rel="noreferrer">#438</a> mandates RLS for tenant isolation. Supabase makes RLS the default path; plain Postgres hosts treat it as an expert feature.</li><li>Two free-tier projects cover staging and production with no billing change. A paid plan ($25/mo Pro) is justified at cutover for daily backups + PITR. Still cheaper than the $5–6/mo Railway footprint plus the time cost of running our own backup cron.</li></ul><p><strong>Connect via raw <code>pg</code> only.</strong> <code>supabase-js</code> adds an HTTP proxy layer (PostgREST) that this codebase has no use for — our reads are all parameterised SQL and benefit from direct TCP. Using <code>pg</code> also means Supabase is a host, not a framework: if we ever outgrow it, the swap is a connection-string change.</p><p><strong>Region (resolved in Phase 1.1, 2026-04-21):</strong> Both Railway app and Supabase prod pinned to <code>us-east-1</code>. Project ref <code>gdqmtevlnumwixevcmgg</code>.</p><h2 id="_0-3-—-migration-tooling-node-pg-migrate" tabindex="-1">0.3 — Migration tooling: node-pg-migrate <a class="header-anchor" href="#_0-3-—-migration-tooling-node-pg-migrate" aria-label="Permalink to &quot;0.3 — Migration tooling: node-pg-migrate&quot;">​</a></h2><p><strong>Decision: <code>node-pg-migrate</code> for schema migrations. Raw parameterised SQL for queries (no ORM, no query builder).</strong></p><table tabindex="0"><thead><tr><th>Criterion</th><th><strong>node-pg-migrate</strong></th><th>drizzle-kit</th><th>prisma</th></tr></thead><tbody><tr><td>Migration format</td><td>Plain <code>.sql</code> / <code>.js</code> up/down</td><td>TS schema → generated SQL</td><td>Schema DSL → generated SQL</td></tr><tr><td>Query layer</td><td>Caller&#39;s choice (<code>pg</code>)</td><td>Drizzle query builder</td><td>Prisma client</td></tr><tr><td>TypeScript required for value</td><td>No</td><td>Yes (VERA is plain JS)</td><td>No but heavy</td></tr><tr><td>Owner can read migrations without learning a DSL</td><td>✅</td><td>➖</td><td>❌</td></tr><tr><td>Depth of buy-in</td><td>Shallow</td><td>Medium</td><td>Deep</td></tr></tbody></table><p><strong>Why node-pg-migrate wins:</strong></p><ul><li>VERA is plain JavaScript. Drizzle&#39;s value is its TypeScript schema + type-safe queries. Without TS that value evaporates and we&#39;d be adopting a framework for its migration runner alone — that&#39;s what node-pg-migrate already does, smaller.</li><li>The existing DAL&#39;s &quot;typed update helpers&quot; (<code>updateProjectPM</code>, <code>updateBudgetHours</code>, etc.) already give us a small, named, typed-in-practice surface. A query builder is solving a problem we don&#39;t have.</li><li>Migrations as readable SQL files match how Tom inspects Sheets today — the primary artifact stays human-readable.</li><li>Escape hatch: if the DAL grows past ~50 typed query sites and type safety starts to pay off, swapping <code>node-pg-migrate</code> + <code>pg</code> for Drizzle later is ~1 week of work and doesn&#39;t touch the migration history.</li></ul><h2 id="_0-4-—-confidence-window-8-weeks-accept-default" tabindex="-1">0.4 — Confidence window: 8 weeks (accept default) <a class="header-anchor" href="#_0-4-—-confidence-window-8-weeks-accept-default" aria-label="Permalink to &quot;0.4 — Confidence window: 8 weeks (accept default)&quot;">​</a></h2><p><strong>Decision: 8-week confidence window before Phase 4 deletes the Sheets path. No shortening.</strong></p><p>Rationale:</p><ul><li>Two full month-end cycles pass in 8 weeks. Every retainer is exercised at least twice under the new backend.</li><li>Snapshot-dependent questions (&quot;show me project spend on Nov 13&quot;) test the daily-snapshot cron — those surface monthly, not weekly.</li><li>Phase 4&#39;s &quot;delete the Sheets path&quot; commit is gated on <em>zero</em> diff-store mismatches and <em>zero</em> flag flips over the window. Any incident resets the clock by the same amount, per <a href="https://github.com/talktalkmake/VERA/issues/438" target="_blank" rel="noreferrer">#438</a>.</li><li>Earliest realistic Phase 4 date, assuming Phase 1 starts 2026-04-22 and each phase lands on its estimated duration: Phase 1 ends ~2026-05-06, Phase 2 ends ~2026-05-14, Phase 3 ends ~2026-05-21, confidence window closes ~2026-07-16, Phase 4 ends ~2026-07-22. Add 25% buffer → ~2026-08-05.</li></ul><h2 id="go-no-go-signal-for-phase-1" tabindex="-1">Go/no-go signal for Phase 1 <a class="header-anchor" href="#go-no-go-signal-for-phase-1" aria-label="Permalink to &quot;Go/no-go signal for Phase 1&quot;">​</a></h2><p>All three decisions are recorded. The contract in §0.1 is the surface Phase 1 must preserve. Phase 1 opens with:</p><ol><li>Provision Supabase <code>vera-staging</code> + <code>vera-prod</code>; record connection strings in Railway env vars (step 1.1).</li><li>Add <code>pg</code>, <code>pg-pool</code>, <code>node-pg-migrate</code> to <code>package.json</code> (step 1.2).</li><li>Write migrations for all 14 tables using <a href="https://github.com/talktalkmake/VERA/blob/main/CLAUDE.md" target="_blank" rel="noreferrer">CLAUDE.md</a>&#39;s column-index tables as the authoritative source (step 1.3).</li></ol><p>No code in this branch yet. This memo is the only artifact of Phase 0.</p>',41)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
